import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import test from "node:test";
import vm from "node:vm";

// Reproduces https://www.youtube.com/watch?v=iNvk3JHSpzk. Its menu lists Korean, Korean (auto),
// English (auto) and Indonesian (auto), but with captions off the player's default
// getOption("captions", "tracklist") omits every auto-generated track once a manual one exists.
const mainSource = readFileSync(new URL("../extension/content/youtube-capture-main.js", import.meta.url), "utf8");
const bridgeSource = readFileSync(new URL("../extension/content/youtube-capture-bridge.js", import.meta.url), "utf8");
const videoId = "iNvk3JHSpzk";
const base = `https://www.youtube.com/api/timedtext?v=${videoId}`;
const body = JSON.stringify({ events: [{ tStartMs: 0, dDurationMs: 2000, segs: [{ utf8: "Hello" }] }] });

const allTracks = [
  { languageCode: "ko", kind: "" },
  { languageCode: "ko", kind: "asr" },
  { languageCode: "en", kind: "asr" },
  { languageCode: "id", kind: "asr" }
];

function harness({ currentTime, tracks = allTracks } = {}) {
  const listeners = [];
  const timeouts = new Set();
  const calls = { setOption: [], toggle: 0 };
  let selectedTrack = null;
  let captionsOn = false;
  const playback = { currentTime };
  const player = {
    ...(currentTime === undefined ? {} : { getCurrentTime: () => playback.currentTime }),
    getPlayerResponse: () => ({ videoDetails: { videoId }, captions: { playerCaptionsTracklistRenderer: { captionTracks: [] } } }),
    // Mirrors YouTube: auto-generated tracks are only returned when includeAsr is requested.
    getOption: (_module, option, args) => {
      if (option === "tracklist") return args?.includeAsr ? tracks : tracks.filter((track) => track.kind !== "asr");
      return selectedTrack;
    },
    setOption: (_module, _option, track) => { calls.setOption.push(track); selectedTrack = track; },
    toggleSubtitles: () => { calls.toggle += 1; captionsOn = !captionsOn; },
    querySelector: () => ({ getAttribute: () => String(captionsOn) })
  };
  class Xhr {
    constructor() { this.listeners = []; this.status = 200; }
    open(_method, url) { this.responseURL = url; }
    addEventListener(type, callback) { if (type === "load") this.listeners.push(callback); }
    respond(text) { this.responseText = text; for (const callback of this.listeners.splice(0)) callback(); }
  }
  const fetched = [];
  const window = {
    // Mirrors YouTube: "variant" only exists on auto-generated tracks, so a human track URL that
    // still carries it comes back 200 with an empty body.
    fetch: async (input) => {
      const url = new URL(String(typeof input === "string" ? input : input.url));
      fetched.push(url);
      const text = url.searchParams.has("variant") && url.searchParams.get("kind") !== "asr" ? "" : body;
      return { ok: true, url: url.toString(), text: async () => text, clone: () => ({ text: async () => text }) };
    },
    addEventListener(type, listener) { if (type === "message") listeners.push(listener); },
    postMessage(data, origin) { for (const listener of listeners) listener({ data, origin, source: window }); }
  };
  const context = {
    URL, XMLHttpRequest: Xhr, window,
    location: { origin: "https://www.youtube.com" },
    document: { getElementById: () => player },
    setTimeout(callback, delay = 0) { callback.delay = delay; timeouts.add(callback); return callback; },
    clearTimeout(callback) { timeouts.delete(callback); }
  };
  vm.runInNewContext(bridgeSource, context);
  vm.runInNewContext(mainSource, context);
  return {
    context, calls, timeouts, playback, fetched,
    // Advances only short polling timers, never the bridge's or the restore's long timeouts.
    tick() { for (const callback of [...timeouts]) { if (callback.delay > 1000) continue; timeouts.delete(callback); callback(); } },
    playerResponds(lang, kind, variant) {
      const xhr = new Xhr();
      xhr.open("GET", `${base}&lang=${lang}${kind ? "&kind=asr" : ""}${variant ? `&variant=${variant}` : ""}&pot=x&fmt=json3`);
      xhr.respond(body);
    }
  };
}

for (const [languageCode, isAutoGenerated] of [["en", true], ["id", true], ["ko", true]]) {
  test(`captions off: requesting the ${languageCode} auto-generated track switches the player to it`, async () => {
    const h = harness();
    const pending = h.context.astYoutubeCaptionCapture.request({ videoId, languageCode, isAutoGenerated });
    assert.equal(h.calls.setOption.at(-1)?.languageCode, languageCode, "player was asked to select the track");
    assert.equal(h.calls.setOption.at(-1)?.kind, "asr");
    assert.equal(h.calls.toggle, 1, "captions were turned on so the player requests it");
    h.playerResponds(languageCode, true);
    const caption = await pending;
    assert.equal(caption?.languageCode, languageCode);
    assert.equal(caption?.isAutoGenerated, true);
  });
}

// Right after a page load the player has no PO token yet: a caption request then comes back
// empty while the captions button stays on, so the player is only asked once playback settles.
test("waits until two seconds of playback before asking the player for a track", async () => {
  const h = harness({ currentTime: 0.4 });
  const pending = h.context.astYoutubeCaptionCapture.request({ videoId, languageCode: "en", isAutoGenerated: true });
  assert.equal(h.calls.setOption.length, 0, "no track switch right after load");
  assert.equal(h.calls.toggle, 0, "captions stay off while waiting");
  h.tick();
  assert.equal(h.calls.setOption.length, 0);
  h.playback.currentTime = 2.1;
  h.tick();
  assert.equal(h.calls.setOption.at(-1)?.languageCode, "en");
  h.playerResponds("en", true);
  assert.equal((await pending)?.languageCode, "en");
});

test("a paused video does not block the request forever", () => {
  const h = harness({ currentTime: 0 });
  h.context.astYoutubeCaptionCapture.request({ videoId, languageCode: "en", isAutoGenerated: true });
  for (let i = 0; i < 20 && h.calls.setOption.length === 0; i += 1) h.tick();
  assert.equal(h.calls.setOption.at(-1)?.languageCode, "en");
});

test("human target captions drop the auto-generated track's variant from the reused player URL", async () => {
  const h = harness();
  // The player's last request was the English auto-generated track with a timing variant.
  h.playerResponds("en", true, "timing-optimized");
  const caption = await h.context.astYoutubeCaptionCapture.requestTarget({ videoId, targetLanguage: "ko" });
  const humanUrl = h.fetched.find((url) => url.searchParams.get("lang") === "ko" && !url.searchParams.has("tlang"));
  assert.ok(humanUrl, "a human Korean track was requested");
  assert.equal(humanUrl.searchParams.has("variant"), false, "variant belongs to the en auto track only");
  assert.equal(caption?.source, "human");
  assert.equal(caption?.languageCode, "ko");
});

test("a video with no caption tracks answers the request at once instead of after the 10s timeout", async () => {
  const h = harness({ tracks: [] });
  let settled = false;
  const pending = h.context.astYoutubeCaptionCapture.request({ videoId }).then((caption) => { settled = true; return caption; });
  await new Promise((resolve) => setImmediate(resolve));
  assert.equal(settled, true, "resolved without waiting for the bridge timeout");
  assert.equal(await pending, null);
  assert.equal(h.calls.setOption.length, 0);
  assert.equal(h.calls.toggle, 0);
});
